import java.nio.file.*;
import java.util.*;
public class KiwamiEntryProbe {
 public static void main(String[]args)throws Exception{
  var fs=Class.forName("zombie.ZomboidFileSystem");Object folder=fs.getField("base").get(fs.getField("instance").get(null));var game=Path.of("F:/SteamLibrary/steamapps/common/ProjectZomboid").toFile().getCanonicalFile();for(String key:new String[]{"absoluteFile","canonicalFile"})folder.getClass().getField(key).set(folder,game);folder.getClass().getField("canonicalUri").set(folder,game.toURI());folder.getClass().getField("lowercaseUri").set(folder,java.net.URI.create(game.toURI().toString().toLowerCase(java.util.Locale.ROOT)));
  var node=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimNode");var state=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimState");var vars=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimationVariableSource");var source=Class.forName("zombie.core.skinnedmodel.advancedanimation.IAnimationVariableSource");var set=vars.getMethod("setVariable",String.class,String.class);var select=state.getMethod("getAnimNodes",source,List.class);
  Object entry=node.getMethod("Parse",String.class).invoke(null,args[0]);Object idle=node.getMethod("Parse",String.class).invoke(null,args[1]);if(node.getField("isLooped").getBoolean(entry)||node.getField("earlyTransitionOut").getBoolean(entry)||Math.abs(node.getField("blendOutTime").getFloat(entry)-.3f)>.00001)throw new AssertionError("full entry and native fade settings");
  Object st=state.getConstructor().newInstance(),v=vars.getConstructor().newInstance();state.getMethod("addNode",node).invoke(st,idle);state.getMethod("addNode",node).invoke(st,entry);set.invoke(v,"PerformingAction","ProjectYakuza_DD_StyleEntry");set.invoke(v,"isTurning90","false");set.invoke(v,"isTurningAround","false");List<?> active=(List<?>)select.invoke(st,v,new ArrayList<>());if(active.size()!=1||active.get(0)!=entry)throw new AssertionError("entry selection");
  set.invoke(v,"PerformingAction","");List<?> ended=(List<?>)select.invoke(st,v,new ArrayList<>());if(ended.size()!=1||ended.get(0)!=idle||!node.getField("animName").get(idle).equals("Bob_Idle"))throw new AssertionError("native idle fallback");
  Object aim=node.getMethod("Parse",String.class).invoke(null,args[2]);Object aimState=state.getConstructor().newInstance();state.getMethod("addNode",node).invoke(aimState,aim);set.invoke(v,"Weapon","1handed");set.invoke(v,"Aim","true");set.invoke(v,"ProjectYakuzaActive","true");set.invoke(v,"ProjectYakuzaStyle","dragon_of_dojima");List<?> aimed=(List<?>)select.invoke(aimState,v,new ArrayList<>());if(aimed.size()!=1||!node.getField("animName").get(aim).equals("Bob_IdleAim1Hand"))throw new AssertionError("native aimed idle");
  for(String group:new String[]{"aim","aim-strafe"})if(Files.exists(Path.of(args[3],"AnimSets/player",group,"ProjectYakuza_DD_CombatIdle.xml")))throw new AssertionError("obsolete custom idle would override native aim");
  System.out.println("PASS native full entry selector, 0.3-second fade, no early cut and return to original Bob_Idle/Bob_IdleAim1Hand after owned action clears; custom idle overrides removed");
 }
}
